# Let me try a different construction for STS(15)
# Using the Bose construction for v = 6n+3 where n=2

from itertools import combinations

def construct_sts_15_bose():
    """
    Bose construction for STS(6n+3)
    For n=2, v=15

    Points: (i, j) where i in {0,1,2} and j in Z_5
    Map to 0-14: point (i,j) -> 5*i + j
    """
    n = 2
    m = 2*n + 1  # m = 5

    blocks = []

    # Type 1: {(i, j), (i, j+k), (i+1, j)} for i in {0,1,2}, j in Z_m, k in {1,...,n}
    # Wait, let me use the correct Bose construction

    # Actually, the Bose construction for STS(6n+3):
    # Points: Z_{2n+1} x {0, 1, 2}
    # For v=15: Z_5 x {0, 1, 2}

    # Blocks of type 1: {(x, 0), (x, 1), (x, 2)} for x in Z_5
    for x in range(5):
        blocks.append(frozenset([(x, 0), (x, 1), (x, 2)]))

    # Blocks of type 2: {(x, i), (y, i), ((x+y)/2, i+1)} for x < y in Z_5, i in {0,1,2}
    # where (x+y)/2 is computed in Z_5 (need 2 to be invertible, which it is in Z_5)
    # Actually, the formula is: {(x, i), (y, i), ((x+y)*inv(2), i+1 mod 3)}
    # In Z_5, inv(2) = 3 (since 2*3 = 6 = 1 mod 5)

    inv2 = 3  # inverse of 2 in Z_5

    for i in range(3):
        for x in range(5):
            for y in range(x+1, 5):
                z = (x + y) * inv2 % 5
                blocks.append(frozenset([(x, i), (y, i), (z, (i+1) % 3)]))

    print(f"Total blocks: {len(blocks)}")

    # Map to 0-14
    def to_int(point):
        return 5 * point[1] + point[0]

    blocks_int = [frozenset(to_int(p) for p in block) for block in blocks]

    # Verify
    pair_count = {}
    for block in blocks_int:
        for pair in combinations(sorted(block), 2):
            pair_count[pair] = pair_count.get(pair, 0) + 1

    all_pairs = list(combinations(range(15), 2))
    print(f"Pairs covered: {len(pair_count)}")
    print(f"Expected pairs: {len(all_pairs)}")

    valid = len(pair_count) == len(all_pairs) and all(c == 1 for c in pair_count.values())
    print(f"STS valid: {valid}")

    if valid:
        return blocks_int

    return None

blocks = construct_sts_15_bose()
if blocks:
    print("STS(15) constructed successfully!")
    print(f"Number of blocks: {len(blocks)}")
    for b in blocks:
        print(sorted(b))

