from itertools import combinations

def construct_bibd_15_3_3():
    n = 2
    m = 5

    blocks = []
    for x in range(5):
        blocks.append(frozenset([(x, 0), (x, 1), (x, 2)]))

    inv2 = 3
    for i in range(3):
        for x in range(5):
            for y in range(x+1, 5):
                z = (x + y) * inv2 % 5
                blocks.append(frozenset([(x, i), (y, i), (z, (i+1) % 3)]))

    def to_int(point):
        return 5 * point[1] + point[0]

    sts_blocks = [frozenset(to_int(p) for p in block) for block in blocks]

    bibd_blocks = []
    for block in sts_blocks:
        bibd_blocks.extend([block, block, block])

    v = 15
    b = 105
    matrix = [[0] * b for _ in range(v)]

    for j, block in enumerate(bibd_blocks):
        for i in block:
            matrix[i][j] = 1

    flat_matrix = [matrix[i][j] for i in range(v) for j in range(b)]
    return flat_matrix

